function ProductsPage() {
  const [searchParams] = useSearchParams();
  const [products, setProducts] = useState(allProducts);
  const [filteredProducts, setFilteredProducts] = useState(allProducts);
  const [showAuth, setShowAuth] = useState(false);
  const [showFilterPanel, setShowFilterPanel] = useState(false);
  const [activeFilters, setActiveFilters] = useState({
    category: '',
    subcategory: '',
    priceRange: [0, 10000],
    sizes: [],
    colors: [],
    brand: '',
    material: '',
    sortBy: 'featured'
  });
  const [filters, setFilters] = useState({
    category: 'all',
    minPrice: 0,
    maxPrice: 50000,
    sortBy: 'name'
  });

  const navigate = useNavigate();
  const { isAuthenticated, loading: authLoading } = useAuth();
  const { addToCart } = useCart();

  // Apply filters whenever products or filter values change
  useEffect(() => {
    let filtered = [...products];

    // Filter by category if not 'all'
    if (filters.category !== 'all') {
      filtered = filtered.filter(item => {
        const itemCategory = (item.category || '').toLowerCase();
        const filterCategory = filters.category.toLowerCase();
        
        // Handle different category mappings
        switch (filterCategory) {
          case 'men':
          case 'kids':
          case 'sale':
            return itemCategory.includes(filterCategory);
          case 'shirts':
            return itemCategory.includes('shirts') || itemCategory.includes('t-shirts');
          case 'jackets':
            return itemCategory.includes('jackets') || itemCategory.includes('blazers');
          case 'pants':
            return itemCategory.includes('pants') || itemCategory.includes('jeans');
          case 'formal':
            return itemCategory.includes('suits') || itemCategory.includes('formal');
          case 'outerwear':
            return itemCategory.includes('outerwear') || itemCategory.includes('jackets');
          case 'accessories':
            return itemCategory.includes('accessories');
          default:
            return itemCategory.includes(filterCategory);
        }
      });
    }

    // Filter by price range
    filtered = filtered.filter(item => 
      item.price >= filters.minPrice && item.price <= filters.maxPrice
    );

    // Sort products based on selected option
    filtered.sort((a, b) => {
      const nameA = (a.name || '').toLowerCase();
      const nameB = (b.name || '').toLowerCase();
      
      switch (filters.sortBy) {
        case 'price-low':
          return a.price - b.price;
        case 'price-high':
          return b.price - a.price;
        case 'rating':
          return (b.rating || 0) - (a.rating || 0);
        case 'name':
        default:
          return nameA.localeCompare(nameB);
      }
    });

    setFilteredProducts(filtered);
  }, [products, filters]);

  // Handle filter changes from ProductFilter component
  const handleFilterChange = (newFilters) => {
    setFilters(newFilters);
  };

  // Handle new filter panel changes
  const handleNewFilterChange = (newFilters) => {
    setActiveFilters(newFilters);
    
    let filtered = [...products];
    
    // Apply category filter
    if (newFilters.category) {
      filtered = filtered.filter(item => 
        item.category === newFilters.category
      );
    }
    
    // Apply subcategory filter
    if (newFilters.subcategory) {
      filtered = filtered.filter(item => 
        item.subcategory === newFilters.subcategory
      );
    }
    
    // Apply price range filter
    filtered = filtered.filter(item => 
      item.price >= newFilters.priceRange[0] && item.price <= newFilters.priceRange[1]
    );
    
    // Apply size filter
    if (newFilters.sizes.length > 0) {
      filtered = filtered.filter(item => 
        item.sizes && item.sizes.some(size => newFilters.sizes.includes(size.name || size))
      );
    }
    
    // Apply color filter
    if (newFilters.colors.length > 0) {
      filtered = filtered.filter(item => 
        item.colors && item.colors.some(color => newFilters.colors.includes(color))
      );
    }
    
    // Apply brand filter
    if (newFilters.brand) {
      filtered = filtered.filter(item => 
        item.brand === newFilters.brand
      );
    }
    
    // Apply material filter
    if (newFilters.material) {
      filtered = filtered.filter(item => 
        item.material === newFilters.material
      );
    }
    
    // Apply sorting
    switch (newFilters.sortBy) {
      case 'price-low':
        filtered.sort((a, b) => a.price - b.price);
        break;
      case 'price-high':
        filtered.sort((a, b) => b.price - a.price);
        break;
      case 'newest':
        filtered.sort((a, b) => (b.newArrival ? 1 : 0) - (a.newArrival ? 1 : 0));
        break;
      case 'rating':
        filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
        break;
      case 'name-asc':
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'name-desc':
        filtered.sort((a, b) => b.name.localeCompare(a.name));
        break;
      default:
        // featured - keep original order
        break;
    }
    
    setFilteredProducts(filtered);
  };

  // Check if filter=true in URL params
  useEffect(() => {
    if (searchParams.get('filter') === 'true') {
      setShowFilterPanel(true);
    }
  }, [searchParams]);

  const handleAddToCart = (product) => {
    if (authLoading) return;
    if (!isAuthenticated) {
      setShowAuth(true);
      return;
    }

    addToCart({ ...product, quantity: 1 });
    alert(`${product.name} added to cart!`);
  };

  return (
    <div className="products-page">
      <div className="container">
        <div className="products-header">
          <h1>All Products</h1>
          <p>Browse our complete collection of premium fashion items</p>
        </div>

        <div className="products-content">
          <ProductFilter 
            filters={filters} 
            onFilterChange={handleFilterChange} 
          />
          
          <div className="products-grid">
            {filteredProducts.length > 0 ? (
              filteredProducts.map(item => (
                <ProductCard key={item._id || item.id} product={item} onAddToCart={handleAddToCart} />
              ))
            ) : (
              <div className="no-products">
                <h3>No products found</h3>
                <p>Try adjusting your filters to see more products.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Filter Panel */}
      <FilterPanel 
        isOpen={showFilterPanel}
        onClose={() => setShowFilterPanel(false)}
        onFilterChange={handleNewFilterChange}
        currentFilters={activeFilters}
      />

      {/* Auth Modal */}
      {showAuth && (
        <AuthModal 
          isOpen={showAuth}
          onClose={() => setShowAuth(false)}
          onLogin={() => navigate('/login')}
          onRegister={() => navigate('/register')}
        />
      )}
    </div>
  );
}

export default ProductsPage;
